const now = new Date().toISOString();
const tenant = "companyA";
const site = "plant1";
const area = "line1";
const asset = "machine7";

// base values
let cycleTime = 28 + Math.random() * 10;        // 28-38
let nozzleTemp = 210 + Math.random() * 15;      // 210-225
let vibration = 0.05 + Math.random() * 0.15;    // 0.05-0.20
let energy = 1.8 + Math.random() * 0.9;         // 1.8-2.7

// anomalies
let severity = "info";
let message = "OK";
const r = Math.random();

if (r < 0.08) {
  cycleTime += 20 + Math.random() * 15;
  severity = "warn";
  message = "Cycle time spike";
}
if (r > 0.92) {
  nozzleTemp -= 20 + Math.random() * 15;
  severity = "warn";
  message = "Nozzle temperature drop";
}
if (r > 0.97) {
  vibration += 0.8 + Math.random() * 0.6;
  severity = "crit";
  message = "High vibration detected";
}

// ---- HARD RULES (override) ----
// İstersen eşikleri değiştir
if (cycleTime >= 120) {
  severity = "crit";
  message = "CycleTime >= 120 (critical)";
} else if (cycleTime >= 100 && severity !== "crit") {
  severity = "warn";
  message = "CycleTime >= 100 (warning)";
}
// -------------------------------

const traceId = `sim-${Date.now()}-${Math.floor(Math.random()*1000)}`;

msg.topic = `uns/${tenant}/${site}/${area}/${asset}/telemetry`;
msg.payload = {
  ts: now,
  source: "node-red",
  type: "telemetry",
  schema: "uns.v1",
  tags: { tenant, site, area, asset },

  // METRICS (Influx/Grafana için temiz alanlar)
  metrics: {
    cycleTime: +cycleTime.toFixed(2),
    nozzleTemp: +nozzleTemp.toFixed(2),
    vibration: +vibration.toFixed(3),
    energyKWh: +energy.toFixed(3),

    // 👇 kolay kullanım (Grafana/Rule/Node-RED)
    severity: severity,
    message: message
  },

  // 👇 Switch node bununla çalışır: msg.payload.severity
  severity,
  message,
  traceId
};

return msg;

// telemetry -> event (warn/crit ise)
// input: msg.topic = .../telemetry
// output: msg.topic = .../event

const p = msg.payload || {};
const sev = (p.severity || (p.metrics && p.metrics.severity) || "info").toLowerCase();

if (sev !== "warn" && sev !== "crit") {
  return null; // info ise event üretme
}

const parts = (msg.topic || "").split("/");
/*
beklenen: uns/companyA/plant1/line1/machine7/telemetry
index:    0   1        2      3     4        5
*/
if (parts.length >= 6) {
  parts[5] = "event";
  msg.topic = parts.join("/");
} else {
  // fallback
  msg.topic = "uns/companyA/plant1/line1/machine7/event";
}

msg.payload = {
  ts: p.ts || new Date().toISOString(),
  source: "node-red",
  type: "event",
  schema: "uns.alarm.v1",
  tags: p.tags || {},
  alarm: {
    severity: sev,
    message: p.message || "Alarm",
    metrics: p.metrics || {},
    traceId: p.traceId || `evt-${Date.now()}`
  }
};

return msg;

const now = new Date().toISOString();
const tenant = "companyA";
const site = "plant1";
const area = "line1";
const asset = "machine7";

const modes = ["auto","manual","setup"];
const state = (Math.random() > 0.03) ? "online" : "offline";
const mode = modes[Math.floor(Math.random()*modes.length)];
const traceId = `status-${Date.now()}-${Math.floor(Math.random()*1000)}`;

msg.topic = `uns/${tenant}/${site}/${area}/${asset}/status`;
msg.payload = {
  ts: now,
  source: "node-red",
  type: "status",
  schema: "uns.v1",
  tags: { tenant, site, area, asset },
  metrics: { state, mode },
  severity: state === "online" ? "info" : "warn",
  message: `Machine is ${state} (${mode})`,
  traceId
};

return msg;

const now = new Date().toISOString();
const tenant = "companyA";
const site = "plant1";
const area = "line1";
const asset = "machine7";
const traceId = `crit-${Date.now()}-${Math.floor(Math.random()*1000)}`;

msg.topic = `uns/${tenant}/${site}/${area}/${asset}/event`;
msg.payload = {
  ts: now,
  source: "node-red",
  type: "event",
  schema: "uns.v1",
  tags: { tenant, site, area, asset },
  severity: "crit",
  message: "Manual critical alarm triggered (demo)",
  metrics: { code: "E-STOP", reason: "Operator pressed emergency stop" },
  traceId
};

return msg;

const now = new Date().toISOString();
const tenant = "companyA";
const site = "plant1";
const area = "line1";
const asset = "machine7";

let cmd = msg.payload;
if (typeof cmd === "string") {
  try { cmd = JSON.parse(cmd); } catch (e) { cmd = { action: cmd }; }
}

const traceId = cmd.traceId || `cmd-${Date.now()}-${Math.floor(Math.random()*1000)}`;
const action = cmd.action || "unknown";

let result = { ok: true, action };
let severity = "info";
let message = "Command executed";

if (action === "setModeManual") { result.mode = "manual"; message = "Mode set to manual"; }
if (action === "setModeAuto") { result.mode = "auto"; message = "Mode set to auto"; }
if (action === "requestSnapshot") {
  result.snapshot = { cycleTime: 33.2, nozzleTemp: 218.1, vibration: 0.12 };
  message = "Snapshot delivered";
}
if (action === "emergencyStop") { severity = "crit"; result.state = "stopped"; message = "Emergency stop executed"; }

msg.topic = `uns/${tenant}/${site}/${area}/${asset}/event`;
msg.payload = {
  ts: now,
  source: "node-red",
  type: "event",
  schema: "uns.v1",
  tags: { tenant, site, area, asset },
  severity,
  message: `CMD result: ${message}`,
  metrics: { cmd, result },
  traceId
};

return msg;

// Aynı alarm OPEN ise tekrar OPEN üretme
// flow context içinde açık alarmlar tutulur
const t = msg.payload?.tags || {};
const k = `open_alarm_key_${t.tenant}_${t.site}_${t.area}_${t.asset}`;
flow.set(k, msg.payload?.traceId || msg.payload?.alarm?.traceId || msg.payload?.traceId || "last-open");

const alarm = msg.payload.alarm;
if (!alarm) return msg;

let active = flow.get("activeAlarms") || {};

if (alarm.state === "OPEN") {
  if (active[alarm.id]) {
    // zaten açık → DROP
    return null;
  }
  active[alarm.id] = {
    openedAt: alarm.openedAt,
    severity: alarm.severity
  };
}

flow.set("activeAlarms", active);
return msg;

// Generate a CLEAR message when telemetry goes back to normal
// IMPORTANT: clearedKey MUST match alarmKey in DB: tenant/site/area/asset

const p = msg.payload || {};
const tags = p.tags || {};
const tenant = tags.tenant;
const site   = tags.site;
const area   = tags.area;
const asset  = tags.asset;

const clearedKey = `${tenant}/${site}/${area}/${asset}`;

msg.topic = `uns/${tenant}/${site}/${area}/${asset}/clear`;
msg.payload = {
  ts: new Date().toISOString(),
  source: "node-red",
  type: "clear",
  schema: "uns.alarm.clear.v1",
  tags,
  clear: {
    reason: `Telemetry back to normal (severity=${p.severity || "info"})`,
    clearedKey
  }
};

return msg;

msg.topic = "uns/companyA/plant1/line1/machine7/ack";
msg.payload = {
  ts: new Date().toISOString(),
  source: "ui",
  type: "ack",
  schema: "uns.alarm.ack.v1",
  tags: {
    tenant: "companyA",
    site: "plant1",
    area: "line1",
    asset: "machine7"
  },
  ack: {
    reason: "ACK from operator"
  }
};
return msg;
